// Basic Variable Deduction
auto count = 100;           // int
auto rate = 3.14159L;       // long double

// Complex Types (e.g., STL Iterators)
std::vector<int> numbers;
auto it = numbers.cbegin(); // Replaces std::vector<int>::const_iterator

// Range-Based Loops
for (auto const& num : numbers) {
    /* num has type const int& */
}

// Lambda Expression Storage (C++11)
auto multiply = [](int a, int b) {
    return a * b;
};

// Generic Lambda (C++14: auto parameter deduction)
auto add = [](auto x, auto y) {
    return x + y;
};
